import { readFileSync } from "node:fs";
import { afterEach, describe, expect, it, vi } from "vitest";
import { generateWithOpenRouter, reviewCoverage } from "../../lib/platform/openrouter";
import { completionMessage, classNamesIn, coverageEvidence, generatedContext, needsStyles, outlineForReview, styleContext, styleGaps } from "../../lib/platform/build-engine";
import { FIXED_STARTER_PATHS } from "../../lib/platform/starter";
import { classesFromStylesRequest, heuristicCss } from "../fixtures/heuristic-css";

/**
 * Evidence: the Kesari Threads app generated by NYNZ 0.4.0 in the approved
 * production validation (project 2ea4dcd1, 2026-11-05). Its stylesheet was
 * written in the last step without seeing the screens' markup, so most class
 * names had no styles; after the returns edit the plan check wrongly reported
 * three built features as "Not built yet".
 */
type Files = Array<{ path: string; content: string }>;
const build: Files = JSON.parse(readFileSync("tests/fixtures/kesari-threads/build.json", "utf8")).files;
const edit: Files = JSON.parse(readFileSync("tests/fixtures/kesari-threads/edit.json", "utf8")).files;
const review = JSON.parse(readFileSync("tests/fixtures/kesari-threads/edit-review.json", "utf8")) as { request: string; steps: string[]; falseFlags: string[] };
const file = (files: Files, path: string) => files.find((item) => item.path === path)!;

function reply(value: unknown, finish = "stop") {
  return new Response(JSON.stringify({ id: crypto.randomUUID(), model: "anthropic/claude-sonnet-5.5", choices: [{ finish_reason: finish, message: { content: JSON.stringify(value) } }], usage: { prompt_tokens: 1000, completion_tokens: 1000, cost: 0.01 } }), { status: 200 });
}

describe("Kesari Threads styling mismatch (reproduced)", () => {
  it("the production stylesheet left most landing and order classes unstyled", () => {
    const gaps = styleGaps(build);
    expect(gaps.byFile["src/components/Landing.tsx"].length).toBeGreaterThanOrEqual(38);
    expect(gaps.byFile["src/components/Orders.tsx"]).toEqual(expect.arrayContaining(["order-card", "line-list", "row-actions"]));
    expect(gaps.byFile["src/components/Landing.tsx"]).toEqual(expect.arrayContaining(["l-nav", "hamburger", "hero-copy"]));
    expect(needsStyles(gaps)).toBe(true);
  });

  it("the old context for the stylesheet step never showed those class names; the new one does", () => {
    const screens = build.filter((item) => item.path !== "src/index.css");
    expect(generatedContext(screens)).not.toMatch(/\bl-nav\b|\bhamburger\b|\border-card\b/);
    const context = styleContext(screens);
    for (const name of ["l-nav", "hamburger", "hero-copy", "order-card", "line-list", "row-actions"]) expect(context).toContain(name);
    expect(context.length).toBeLessThanOrEqual(26_000);
  });

  it("finds class names in strings, template literals and conditional expressions", () => {
    expect(classNamesIn('<a className="btn primary"/><b className={`card ${on ? "card-on" : ""}`}/><i className={open ? "menu open" : "menu"}/>').sort()).toEqual(["btn", "card", "card-on", "menu", "open", "primary"]);
  });
});

describe("stylesheet generation with the screens' class names", () => {
  afterEach(() => { vi.unstubAllEnvs(); vi.unstubAllGlobals(); });

  it("sends the class names to the stylesheet step, then fills what is still unstyled, labelling each paid request first", async () => {
    vi.stubEnv("OPENROUTER_API_KEY", "test-only-key");
    const manifest = { plan: { summary: "Kesari Threads", steps: ["Landing", "Orders"] }, message: "Ready", files: build.map((item) => ({ path: item.path, purpose: item.path })) };
    const events: string[] = [];
    let stylesheetRequest = "";
    let stylesRequest = "";
    vi.stubGlobal("fetch", vi.fn(async (_url: string, init: RequestInit) => {
      const body = JSON.parse(String(init.body));
      const user: string = body.messages[1].content;
      const schema = body.response_format.json_schema.name;
      events.push(`request:${schema}`);
      if (schema === "nynz_styles") { stylesRequest = user; return reply({ files: [{ path: "src/index.css", content: heuristicCss(classesFromStylesRequest(user)) }] }); }
      const paths = (user.split("GENERATE THESE FILES NOW:\n")[1]?.split("\n\n")[0] || "").split("\n").map((line) => line.split(":")[0]).filter(Boolean);
      if (paths.includes("src/index.css")) stylesheetRequest = user;
      // The model returns the same mismatched stylesheet production got.
      return reply({ files: paths.map((path) => file(build, path)) });
    }));
    const completed = build.filter((item) => item.path !== "src/index.css" && !FIXED_STARTER_PATHS.has(item.path));
    const steps: string[] = [];
    const output = await generateWithOpenRouter({ prompt: "Build Kesari Threads", files: [], mode: "create", approvedManifest: manifest, completed, onLabel: (label) => events.push(`label:${label}`), onStep: async (step) => { steps.push(step.label); } });
    expect(stylesheetRequest).toContain("CLASS NAMES THE SCREENS USE");
    for (const name of ["l-nav", "hamburger", "order-card"]) expect(stylesheetRequest).toContain(name);
    expect(stylesRequest).toContain("hamburger");
    expect(steps).toContain("Styles for markup classes");
    const css = output.result.files.find((item) => item.path === "src/index.css")!.content;
    expect(css).toContain(".hamburger{");
    expect(styleGaps(output.result.files).missing.length).toBeLessThan(3);
    // Every paid request is preceded by the label of the step it pays for.
    expect(events).toEqual(["label:index.css", "request:nynz_files", expect.stringMatching(/^label:Styles for \d+ unstyled class names$/), "request:nynz_styles"]);
  });

  it("gives styles to markup a later edit adds", async () => {
    vi.stubEnv("OPENROUTER_API_KEY", "test-only-key");
    // Start from a fully styled app, then edit Returns.tsx to add new markup.
    const styled = edit.map((item) => item.path === "src/index.css" ? { ...item, content: `${item.content}\n${heuristicCss(styleGaps(edit).missing)}` } : item);
    expect(styleGaps(styled).missing).toEqual([]);
    const returns = file(styled, "src/components/Returns.tsx").content;
    const anchor = returns.match(/<h1[^>]*>[^<]*<\/h1>|<h2[^>]*>[^<]*<\/h2>/)![0];
    const manifest = { plan: { summary: "Returns summary", steps: ["Add a returns summary strip"] }, message: "Done", files: [{ path: "src/components/Returns.tsx", purpose: "Add a summary strip" }] };
    let stylesRequest = "";
    vi.stubGlobal("fetch", vi.fn(async (_url: string, init: RequestInit) => {
      const body = JSON.parse(String(init.body));
      const user: string = body.messages[1].content;
      if (body.response_format.json_schema.name === "nynz_styles") { stylesRequest = user; return reply({ files: [{ path: "src/index.css", content: heuristicCss(classesFromStylesRequest(user)) }] }); }
      return reply({ plan: manifest.plan, message: "Done", edits: [{ path: "src/components/Returns.tsx", search: anchor, replace: `${anchor}<div className="returns-summary-strip"><span className="returns-kpi">Returns</span><span className="returns-kpi-value">0</span></div>` }] });
    }));
    const output = await generateWithOpenRouter({ prompt: "Add a returns summary strip", files: styled, mode: "edit", approvedManifest: manifest });
    expect(classesFromStylesRequest(stylesRequest).sort()).toEqual(["returns-kpi", "returns-kpi-value", "returns-summary-strip"]);
    const css = output.result.files.find((item) => item.path === "src/index.css")!.content;
    expect(css).toContain(".returns-summary-strip{");
  });
});

describe("plan check after the Kesari Threads returns edit", () => {
  afterEach(() => { vi.unstubAllEnvs(); vi.unstubAllGlobals(); });

  it("reproduced: the old outline hid the return form, the filters and the dashboard cards", () => {
    expect(review.falseFlags).toHaveLength(3);
    const outline = outlineForReview(edit);
    expect(outline).not.toContain("Record return or exchange");
    expect(outline).not.toContain("Net sales after returns");
    expect(outline).not.toMatch(/All reasons/);
  });

  it("the evidence now includes the code that implements each flagged step", () => {
    const changed = ["src/types.ts", "src/data.ts", "src/store.ts", "src/components/Orders.tsx", "src/components/Returns.tsx", "src/components/Workspace.tsx", "src/components/Dashboard.tsx", "src/components/Reports.tsx"];
    const evidence = coverageEvidence({ steps: review.steps, files: edit, changed });
    expect(evidence).toContain("Record return or exchange");
    expect(evidence).toContain("Net sales after returns");
    expect(evidence).toMatch(/All reasons|reasonFilter|Size issue/);
    expect(evidence.length).toBeLessThanOrEqual(48_000);
  });

  it("an unverifiable step is reported as Couldn't confirm, never as Not built yet", async () => {
    vi.stubEnv("OPENROUTER_API_KEY", "test-only-key");
    let sent = "";
    vi.stubGlobal("fetch", vi.fn(async (_url: string, init: RequestInit) => {
      sent = JSON.parse(String(init.body)).messages[1].content;
      return reply({ steps: review.steps.map((step, index) => ({ step, status: index === 2 ? "unclear" : "built", evidence: index === 2 ? "" : "src/components/Orders.tsx", note: index === 2 ? "filter code not shown" : "" })) });
    }));
    const result = await reviewCoverage({ steps: review.steps, files: edit, changed: ["src/components/Returns.tsx", "src/components/Dashboard.tsx", "src/components/Orders.tsx"] });
    expect(sent).toContain("SOURCE EVIDENCE");
    expect(result.missing).toEqual([]);
    expect(result.unconfirmed).toHaveLength(1);
    const message = completionMessage({ mode: "edit", plan: { summary: "Add returns and exchanges" }, changed: ["src/components/Returns.tsx"], coverage: result });
    expect(message).toContain("Couldn't confirm automatically");
    expect(message).not.toContain("Not built yet");
    expect(completionMessage({ mode: "edit", coverage: { missing: ["Planned file src/x.tsx was not created"] } })).toContain("Not built yet");
  });
});
